async function loadLocal(){await S.identity();[contacts,categories,phoneSorting,appointments,internal]=await Promise.all([S.list('contact'),S.categories(),S.phoneSorting(),S.list('appointment'),M.hubRows()]);}
function deviceRows(){const live=PC.normalizeThreads(P.threads(),contacts,phoneSorting).map(row=>{const saved=row.contact,organization=row.organization||{categoryIds:[],primaryCategoryId:''};return{...row,id:row.id,source:'device',live:true,savedContact:saved,contact:saved,organization,title:row.title,address:row.address,preview:row.preview,at:row.at,unread:row.unread,group:row.group};}),numbers=new Set(live.map(row=>H.phone(row.address)).filter(Boolean)),saved=contacts.filter(c=>!c.lotkeysId&&!numbers.has(H.phone(phoneFor(c)))).map(c=>({id:'contact:'+c.id,source:'device',live:false,savedContact:c,contact:c,organization:c,title:c.name,address:phoneFor(c),preview:'Saved LotKeys contact · no current phone conversation',at:Date.parse(c.updatedAt||c.createdAt||0)||0,unread:0,group:false}));return[...live,...saved];}
function deviceRow(r){const org=r.organization||r.contact,unread=r.unread?`<b class="hub-device-unread">${r.unread>99?'99+':r.unread}</b>`:'',transport=r.live?`<small>${e(r.preview||r.address||'Message')}</small>`:`<small>${e(r.address||r.preview||'Saved contact')}</small>`;return `<button type="button" class="hub-device-row ${r.live?'live':'saved'}" ${r.live?`data-device-thread="${e(r.id)}"`:`data-device-contact="${e(r.savedContact.id)}"`} style="--hub-color:${e(tint(org))}"><span><strong>${e(r.title)}</strong>${transport}<span class="hub-tags">${categoryBadges(org)}</span></span><span class="hub-time">${unread}${e(when(r.at))}</span></button>`;}
function categoryChips(){const roots=categories.filter(c=>!c.parentId),children=parentId=>categories.filter(c=>c.parentId===parentId),chip=(c,child=false)=>`<button type="button" class="hub-chip ${child?'sub':''} ${selectedCategories.includes(c.id)?'active':''}" aria-pressed="${selectedCategories.includes(c.id)}" style="--hub-color:${e(H.color(c.color)||accent())}" data-category="${e(c.id)}"><span class="hub-dot"></span>${child?'↳ ':''}${e(c.name)}</button>`;return roots.map(root=>chip(root)+children(root.id).map(child=>chip(child,true)).join('')).join('');}
