function bindFilters(){const p=panel();$$('[data-scope]',p).forEach(b=>b.onclick=()=>{scope=b.dataset.scope;selectedCategories=[];filter='all';paintFilters();paintRows();});$$('[data-filter]',p).forEach(b=>b.onclick=()=>{filter=b.dataset.filter;paintFilters();paintRows();});$$('[data-category]',p).forEach(b=>b.onclick=()=>{const id=b.dataset.category;selectedCategories=selectedCategories.includes(id)?selectedCategories.filter(x=>x!==id):[...selectedCategories,id];filter='all';paintFilters();paintRows();});$('[data-category-all]',p)?.addEventListener('click',()=>{selectedCategories=[];filter='all';paintFilters();paintRows();});action($('#hub-organize',p),editCategories);}
