async function open({refresh:remote=true}={}){if(document.body.dataset.lotkeysLocked==='true')return;const epoch=++homeEpoch,p=M.hubMount();p.dataset.hub='home';p.innerHTML=`<section class="hub-shell"><header class="hub-top"><div class="hub-brand"><img src="./assets/lotkeys-icon-192.png" alt=""><div><strong>LotKeys</strong><small>Hub</small></div></div><input id="hub-search" type="search" class="hub-search" placeholder="Search name, number or email" aria-label="Search Hub" value="${e(query)}"><div class="hub-clock"><strong>${e(time(Date.now()))}</strong>${e(new Date().toLocaleDateString())}</div></header><div class="hub-tabs-wrap" id="hub-filters"></div><div class="hub-list" id="hub-list"><div class="hub-empty">Opening your private Hub…</div></div><div class="hub-actions"><button class="hub-fab" id="hub-calendar" aria-label="Calendar" title="Calendar">📅</button><button class="hub-fab" id="hub-call" aria-label="Call" title="Call">☎</button><button class="hub-fab main" id="hub-plus" aria-label="Add to Hub">＋</button></div></section>`;$('#hub-search',p).oninput=event=>{query=event.target.value;paintRows();};action($('#hub-calendar',p),()=>calendar());action($('#hub-plus',p),()=>plusMenu());action($('#hub-call',p),()=>callMenu());try{await loadLocal();if(epoch!==homeEpoch||!home())return;paintFilters();paintRows();if(P.status().native||P.status().connected)P.refreshThreads().then(()=>refresh()).catch(err=>{lastError=err.message;paintStatus();});if(remote){S.sync().then(()=>refresh()).catch(err=>{lastError=err.message;paintStatus();});M.refresh().catch(()=>{});}}catch(err){if(epoch===homeEpoch){$('#hub-list',p).innerHTML=`<div class="hub-empty"><strong>Sign in to use your private Hub</strong>${e(err.message)}<br>Internal LotKeys messaging remains available after account setup.</div>`;paintFilters();}}}
async function refresh(){if(!shown())return;const epoch=homeEpoch;try{await loadLocal();if(epoch!==homeEpoch)return;if(home()){paintFilters();paintRows();}}catch(err){lastError=err.message;}}
function scheduleRefresh(){clearTimeout(refreshTimer);refreshTimer=setTimeout(refresh,140);}
function updateBadge(){const unread=internal.reduce((n,r)=>n+(r.unread||0),0)+deviceRows().reduce((n,r)=>n+(r.live?(r.unread||0):0),0),nav=$('#chat-nav-btn');if(!nav)return;let badge=$('.hub-nav-badge',nav);if(!badge){badge=document.createElement('b');badge.className='hub-nav-badge';nav.append(badge);}badge.textContent=unread>99?'99+':String(unread);badge.hidden=!unread;}
function plusMenu(contactId='',unused='',internalId=''){const d=modal('Add to Hub',`<div class="hub-grid"><button class="hub-btn primary" data-add="contact">＋ Customer / contact</button><button class="hub-btn" data-add="appointment">▦ Appointment</button><button class="hub-btn" data-add="note">📝 Note</button><button class="hub-btn" data-add="file">Photo / document</button><button class="hub-btn" data-add="chat">LotKeys chat / group</button><button class="hub-btn" data-add="category">Device categories</button></div><p class="hub-caption">Customer records stay private. LotKeys chat remains separate from the Device organization area.</p>`);$$('[data-add]',d).forEach(b=>action(b,async()=>{const a=b.dataset.add;d.close();if(a==='contact')return editContact();if(a==='appointment')return editAppointment(null,{contactId,internalId});if(a==='chat')return M.newChat();if(a==='category')return editCategories();const c=contactId?await S.get('contact',contactId):await chooseContact(internalId);if(!c)return;if(a==='note')return noteDialog(c.id);return attachments(c.id);}));}
function callMenu(){const d=modal('Call',`<div class="hub-grid"><button id="hub-call-internal" class="hub-btn primary">LotKeys VoIP</button><button id="hub-call-customer" class="hub-btn">Call a saved contact</button></div><p class="hub-caption">Customer calls open your device’s calling application. They do not become LotKeys VoIP calls.</p>`);action($('#hub-call-internal',d),()=>{d.close();M.call();});action($('#hub-call-customer',d),async()=>{d.close();const c=await chooseContact();if(c&&H.validPhone(phoneFor(c)))location.href='tel:'+H.phone(phoneFor(c));});}
const trustModes=[['ask','Ask Every Time','This computer needs phone approval every time.'],['36h','36 Hours · Default','Foreground LotKeys use renews trust for 36 hours.'],['7d','7 Days','Foreground LotKeys use renews trust for seven days.'],['until-disconnect','Until I Disconnect','For a personal computer. Trust ends when you disconnect or forget it.']];
async function pairPhone(){const pairing=await P.startPairing({trustMode:'36h'}),d=modal('Connect Android phone',`<div class="hub-pair-code" aria-label="Four digit matching code">${e(pairing.code)}</div><p class="hub-pair-lead"><strong>Open LotKeys Hub on the phone.</strong><br>The phone will show this same code and the computer name. Tap Approve & Connect there—nothing needs to be typed.</p><div class="hub-status amber"><span class="hub-coverage-dot"></span><span id="hub-pair-wait">Waiting for phone approval…</span></div><div class="hub-end"><button class="hub-btn danger" id="hub-pair-cancel">Cancel pairing</button></div><p class="hub-caption">This is an internet connection, not Bluetooth. Both devices must be signed into the same LotKeys Google account. The code expires after five minutes.</p>`);pairDialog='pc:'+pairing.sessionId;d._dirty=false;const timer=setInterval(()=>{const s=P.status();if(!d.isConnected){clearInterval(timer);return;}if(s.connected){d.close();toast('Phone connected.');return;}const left=Math.max(0,Math.ceil((pairing.expiresAt-Date.now())/1000));$('#hub-pair-wait',d).textContent=left?`Waiting for phone approval · ${Math.floor(left/60)}:${String(left%60).padStart(2,'0')}`:'Pairing expired.';},500);d._cleanup=()=>{clearInterval(timer);pairDialog='';};action($('#hub-pair-cancel',d),async()=>{d._dirty=false;await P.cancelPairing();d.close();});}
