function download(blob,name){const u=URL.createObjectURL(blob),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),30000);}
async function viewFile(id,fileId,save=false){const c=await S.get('contact',id),f=c?.attachments?.find(x=>x.id===fileId);if(!f)return;const b=await S.blob(id,fileId);if(save||!/^image\/(jpeg|png|webp)$/i.test(f.type)){download(b,f.name);toast('Saved a copy. Open that file to print it; this copy is outside Hub deletion.');return;}const u=URL.createObjectURL(b),d=modal(f.name,`<img class="hub-preview-image" alt="Customer attachment" src="${u}"><div class="hub-end"><button class="hub-btn" id="hub-image-download">Save / print copy</button></div>`);d._cleanup=()=>URL.revokeObjectURL(u);$('#hub-image-download',d).onclick=()=>download(b,f.name);}
async function camera(id,onSaved){if(!navigator.mediaDevices?.getUserMedia)throw Error('In-app camera needs HTTPS and camera support. Choose a file instead.');const d=modal('Camera · private customer attachment',`<video id="hub-camera" class="hub-camera" autoplay muted playsinline></video><img id="hub-capture-preview" class="hub-preview-image" hidden alt="Captured customer photo"><canvas hidden id="hub-camera-canvas"></canvas><p class="hub-caption">LotKeys does not add camera captures to your phone gallery. A temporary capture stays in browser memory until saved to Drive or discarded.</p><div class="hub-end"><button id="hub-capture" class="hub-btn primary">Take photo</button><button id="hub-retake" class="hub-btn" hidden>Retake</button><button id="hub-save-capture" class="hub-btn primary" hidden>Save to customer</button></div><div id="hub-camera-status" class="hub-caption"></div>`);let stream,captured,preview='';d._cleanup=()=>{stream?.getTracks().forEach(t=>t.stop());if(preview)URL.revokeObjectURL(preview);captured=null;};try{stream=await navigator.mediaDevices.getUserMedia({video:{facingMode:{ideal:'environment'},width:{ideal:1920}},audio:false});if(!d.isConnected){stream.getTracks().forEach(t=>t.stop());return;}$('#hub-camera',d).srcObject=stream;}catch(err){report(Error('Camera permission was denied or the camera is unavailable. Use Choose files instead.'),d);return;}action($('#hub-capture',d),async()=>{const v=$('#hub-camera',d),canvas=$('#hub-camera-canvas',d);if(!v.videoWidth)throw Error('The camera preview is not ready.');canvas.width=v.videoWidth;canvas.height=v.videoHeight;canvas.getContext('2d').drawImage(v,0,0);captured=await new Promise(r=>canvas.toBlob(r,'image/jpeg',.92));if(!captured)throw Error('Could not capture this photo.');preview=URL.createObjectURL(captured);$('#hub-capture-preview',d).src=preview;$('#hub-capture-preview',d).hidden=false;v.hidden=true;$('#hub-capture',d).hidden=true;$('#hub-retake',d).hidden=false;$('#hub-save-capture',d).hidden=false;});$('#hub-retake',d).onclick=()=>{URL.revokeObjectURL(preview);preview='';captured=null;$('#hub-capture-preview',d).hidden=true;$('#hub-camera',d).hidden=false;$('#hub-capture',d).hidden=false;$('#hub-retake',d).hidden=true;$('#hub-save-capture',d).hidden=true;};action($('#hub-save-capture',d),async()=>{await S.upload(id,new File([captured],'Customer photo '+new Date().toISOString().replace(/[:.]/g,'-')+'.jpg',{type:'image/jpeg'}),p=>$('#hub-camera-status',d).textContent='Uploading '+p+'%');d.close();await onSaved?.();});}
function vehicleLabel(v){return v?[v.year,v.make,v.model].filter(Boolean).join(' ')+' · STK #'+(v.stock||'—'):'';}
function currentVehicle(a){return vehicles.find(v=>v.id===a.vehicleId);}
function appointmentCard(a){const c=contacts.find(c=>c.id===a.contactId),v=currentVehicle(a);return `<button type="button" class="hub-appointment" data-appt="${e(a.id)}" style="--hub-color:${e(tint(c))}"><span class="hub-ap-time">${e(time(a.start))}<small>${Math.round((Date.parse(a.end)-Date.parse(a.start))/60000)} min</small></span><span class="hub-ap-photo" data-vehicle-photo="${e(v?.id||'')}"></span><span class="hub-ap-copy"><strong>${e(c?.name||a.customerName||a.title)}${c&&phoneFor(c)?' · '+e(phoneFor(c)):''}</strong><b>${e(v?vehicleLabel(v):a.vehicleLabel||'No vehicle linked')}${v?' · '+e(fmt(v.odometer))+' '+e(v.odometerUnit||'KM'):''}</b>${v?`<span>${v.price===''?'Price not set':'$'+e(fmt(v.price))}</span>`:''}<small>${e(a.kind||'Appointment')} · ${e(a.status||'Tentative')}</small></span></button>`;}
const thumbURLs=new Set();
function paintThumbs(root){$$('[data-vehicle-photo]',root).forEach(n=>{const v=vehicles.find(x=>x.id===n.dataset.vehiclePhoto),blob=v?.photos?.[0]?.blob;if(blob instanceof Blob){const u=URL.createObjectURL(blob);thumbURLs.add(u);n.innerHTML=`<img src="${u}" alt="Vehicle thumbnail">`;}else n.innerHTML='<img src="./assets/vehicle-placeholder.webp" alt="Vehicle">';});}
function clearThumbs(){for(const u of thumbURLs)URL.revokeObjectURL(u);thumbURLs.clear();}
async function calendar(day=H.localDay(),initialView='month'){await loadLocal();vehicles=await Core.DB.all('vehicles');let selected=day,anchor=new Date(day+'T12:00:00'),view=initialView;const d=modal('Calendar',`<div class="hub-calendar-bar"><div class="hub-end"><button class="hub-btn" data-view="month">Month</button><button class="hub-btn" data-view="week">Week</button><button class="hub-btn" data-view="day">Day</button></div><div class="hub-end"><button class="hub-btn" id="hub-cal-prev" aria-label="Previous period">‹</button><button class="hub-btn" id="hub-cal-today">Today</button><button class="hub-btn" id="hub-cal-next" aria-label="Next period">›</button><button class="hub-btn primary" id="hub-cal-add">＋ Appointment</button></div></div><h3 id="hub-cal-title"></h3><div id="hub-cal-grid"></div><div id="hub-cal-agenda"></div><p class="hub-caption">Times display in ${e(Intl.DateTimeFormat().resolvedOptions().timeZone)}. This is your private Hub calendar; .ics export is available per appointment. Google/Outlook calendars are not synchronized automatically.</p>`,'calendar');
const draw=async()=>{appointments=await S.list('appointment');if(!d.isConnected)return;clearThumbs();$$('[data-view]',d).forEach(b=>b.classList.toggle('primary',b.dataset.view===view));$('#hub-cal-title',d).textContent=anchor.toLocaleDateString([],{month:'long',year:'numeric'});const grid=$('#hub-cal-grid',d);let days;if(view==='month')days=H.monthCells(anchor);else if(view==='week'){const start=new Date(anchor);start.setDate(start.getDate()-start.getDay());days=Array.from({length:7},(_,i)=>{const date=new Date(start);date.setDate(start.getDate()+i);return date;});}else days=[];grid.className=days.length?'hub-month':'';grid.innerHTML=days.length?['Sun','Mon','Tue','Wed','Thu','Fri','Sat'].map(x=>`<div class="hub-dayname">${x}</div>`).join('')+days.map(date=>{const key=H.localDay(date),appts=H.agenda(appointments,key);return `<button class="hub-day ${date.getMonth()!==anchor.getMonth()?'other':''} ${key===H.localDay()?'today':''} ${key===selected?'selected':''}" type="button" data-day="${key}" aria-label="${e(date.toDateString())}, ${appts.length} appointments"><strong>${date.getDate()}</strong>${appts.slice(0,3).map(a=>{const c=contacts.find(x=>x.id===a.contactId);return `<span style="--hub-color:${e(tint(c))}">${e(time(a.start))} ${e(c?.name||a.customerName||a.title)}</span>`;}).join('')}${appts.length>3?`<small>+${appts.length-3} more</small>`:''}</button>`;}).join(''):'';$$('[data-day]',grid).forEach(b=>b.onclick=()=>{selected=b.dataset.day;draw();});const dates=view==='week'?days.map(H.localDay):[selected],box=$('#hub-cal-agenda',d);box.innerHTML=dates.map(date=>{const rows=H.agenda(appointments,date);return `<h3>${e(new Date(date+'T12:00:00').toLocaleDateString([],{weekday:'long',month:'short',day:'numeric'}))}</h3>${rows.map(appointmentCard).join('')||'<div class="hub-empty">No appointments.</div>'}`;}).join('');$$('[data-appt]',box).forEach(b=>action(b,()=>viewAppointment(b.dataset.appt,draw)));paintThumbs(box);};$$('[data-view]',d).forEach(b=>action(b,async()=>{view=b.dataset.view;anchor=new Date(selected+'T12:00:00');await draw();}));$('#hub-cal-today',d).onclick=()=>{selected=H.localDay();anchor=new Date(selected+'T12:00:00');draw();};const shift=n=>{if(view==='month'){anchor=new Date(anchor.getFullYear(),anchor.getMonth()+n,1,12);selected=H.localDay(anchor);}else{anchor.setDate(anchor.getDate()+(view==='week'?7:1)*n);selected=H.localDay(anchor);}draw();};$('#hub-cal-prev',d).onclick=()=>shift(-1);$('#hub-cal-next',d).onclick=()=>shift(1);action($('#hub-cal-add',d),()=>editAppointment(null,{date:selected,onSaved:draw}));d._cleanup=clearThumbs;await draw();}
async function editAppointment(id=null,{contactId='',internalId='',date=H.localDay(),onSaved}={}){await loadLocal();const editOwner=await S.identity();vehicles=await Core.DB.all('vehicles');if(internalId&&!contactId){const c=await chooseContact(internalId);if(!c)return;contactId=c.id;await loadLocal();}const old=id?appointments.find(a=>a.id===id):null;let chosenContact=contacts.find(c=>c.id===(old?.contactId||contactId)),chosenVehicle=vehicles.find(v=>v.id===old?.vehicleId);const now=new Date();now.setMinutes(Math.ceil(now.getMinutes()/15)*15,0,0);const start=old?new Date(old.start):new Date(date+'T'+String(now.getHours()).padStart(2,'0')+':'+String(now.getMinutes()).padStart(2,'0'));const d=modal(id?'Edit appointment':'New appointment',`<form id="hub-appt-form"><div class="hub-grid"><label class="hub-field full">Customer / contact search<input type="search" id="hub-appt-contact" placeholder="Name, number, email or alias" value="${e(chosenContact?.name||'')}"></label><div class="full hub-select-list" id="hub-appt-contact-results"></div><label class="hub-field full">Vehicle Profile search<input type="search" id="hub-appt-vehicle" placeholder="Year, make, model, STK # or VIN" value="${e(chosenVehicle?vehicleLabel(chosenVehicle):'')}"></label><div class="full hub-select-list" id="hub-appt-vehicle-results"></div><label class="hub-field">Date<input type="date" id="hub-appt-date" required value="${H.localDay(start)}"></label><label class="hub-field">Time<input type="time" id="hub-appt-time" required value="${String(start.getHours()).padStart(2,'0')+':'+String(start.getMinutes()).padStart(2,'0')}"></label><label class="hub-field">Duration (minutes)<input type="number" min="5" max="1440" step="5" id="hub-appt-duration" value="${old?Math.round((Date.parse(old.end)-Date.parse(old.start))/60000):30}"></label><label class="hub-field">Status<select id="hub-appt-status">${['Tentative','Confirmed','Arrived','Completed','Cancelled','No show'].map(x=>`<option ${old?.status===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="hub-field">Type<select id="hub-appt-kind">${['Test drive','Showroom visit','Phone appointment','Delivery','Follow-up','Other'].map(x=>`<option ${old?.kind===x?'selected':''}>${x}</option>`).join('')}</select></label><label class="hub-field">Location<input id="hub-appt-location" maxlength="300" value="${e(old?.location||'')}"></label><label class="hub-field full">Appointment notes<textarea rows="3" id="hub-appt-notes" maxlength="3000">${e(old?.notes||'')}</textarea></label></div><p class="hub-caption">Choose a result to link it. Saving here does not send an invitation or customer message.</p><div class="hub-end"><button class="hub-btn primary" id="hub-appt-save" type="submit">Save appointment</button></div></form>`);
const renderContact=()=>{const box=$('#hub-appt-contact-results',d),q=$('#hub-appt-contact',d).value;box.innerHTML=chosenContact?`<div class="hub-selected">✓ ${e(chosenContact.name)} · ${e(phoneFor(chosenContact))}</div>`:contacts.filter(c=>H.matches(c,q)).slice(0,8).map(c=>`<button class="hub-btn" type="button" data-appt-c="${e(c.id)}">${e(c.name)} · ${e(phoneFor(c))}</button>`).join('')||'<span class="hub-caption">No matching saved contact. Add the contact from Hub ＋ first.</span>';$$('[data-appt-c]',box).forEach(b=>b.onclick=()=>{chosenContact=contacts.find(c=>c.id===b.dataset.apptC);$('#hub-appt-contact',d).value=chosenContact.name;renderContact();});};$('#hub-appt-contact',d).oninput=()=>{chosenContact=null;renderContact();};renderContact();const renderVehicle=()=>{const box=$('#hub-appt-vehicle-results',d),q=$('#hub-appt-vehicle',d).value.trim().toLowerCase();box.innerHTML=chosenVehicle?`<div class="hub-selected">✓ ${e(vehicleLabel(chosenVehicle))}</div>`:q?vehicles.filter(v=>(vehicleLabel(v)+' '+(v.vin||'')).toLowerCase().includes(q)).slice(0,6).map(v=>`<button class="hub-btn" type="button" data-appt-v="${e(v.id)}">${e(vehicleLabel(v))}</button>`).join('')||'<span class="hub-caption">No matching cached Vehicle Profile.</span>':'<span class="hub-caption">Optional: leave blank for a general appointment.</span>';$$('[data-appt-v]',box).forEach(b=>b.onclick=()=>{chosenVehicle=vehicles.find(v=>v.id===b.dataset.apptV);$('#hub-appt-vehicle',d).value=vehicleLabel(chosenVehicle);renderVehicle();});};$('#hub-appt-vehicle',d).oninput=()=>{chosenVehicle=null;renderVehicle();};renderVehicle();$('#hub-appt-form',d).onsubmit=async event=>{event.preventDefault();const b=$('#hub-appt-save',d);if(b.disabled)return;b.disabled=true;try{if(!chosenContact)throw Error('Choose a saved contact from the search results.');if($('#hub-appt-vehicle',d).value.trim()&&!chosenVehicle)throw Error('Choose a Vehicle Profile result or clear the vehicle search.');const minutes=Number($('#hub-appt-duration',d).value);if(!Number.isFinite(minutes)||minutes<5||minutes>1440)throw Error('Duration must be 5 to 1,440 minutes.');const s=H.atLocal($('#hub-appt-date',d).value,$('#hub-appt-time',d).value),a={...old,_owner:editOwner,id:old?.id||H.uid('APPT'),contactId:chosenContact.id,customerName:chosenContact.name,vehicleId:chosenVehicle?.id||'',vehicleLabel:vehicleLabel(chosenVehicle),title:chosenContact.name+' · '+$('#hub-appt-kind',d).value,start:s,end:new Date(Date.parse(s)+minutes*60000).toISOString(),timezone:Intl.DateTimeFormat().resolvedOptions().timeZone,status:$('#hub-appt-status',d).value,kind:$('#hub-appt-kind',d).value,location:$('#hub-appt-location',d).value.trim(),notes:$('#hub-appt-notes',d).value.trim()};const collisions=H.overlap(await S.list('appointment'),a);if(collisions.length&&!confirm('This overlaps '+collisions.length+' appointment(s). Save anyway?'))return;await S.save('appointment',a);d.close();toast('Appointment saved; Drive sync queued.');await onSaved?.();await refresh();}catch(err){report(err,d);}finally{b.disabled=false;}};}
async function viewAppointment(id,onChanged){await loadLocal();vehicles=await Core.DB.all('vehicles');const a=appointments.find(x=>x.id===id);if(!a)return;const c=contacts.find(x=>x.id===a.contactId),v=currentVehicle(a),d=modal(a.kind||'Appointment',`${appointmentCard(a)}<p>${e(new Date(a.start).toLocaleString())} – ${e(time(a.end))}</p><p>${e(a.location||'')}</p><p style="white-space:pre-wrap">${e(a.notes||'')}</p><div class="hub-end"><button class="hub-btn" id="hub-appt-open-contact">Contact</button><button class="hub-btn" id="hub-appt-open-vehicle" ${v?'':'disabled'}>Vehicle Profile</button><button class="hub-btn primary" id="hub-appt-edit">Edit</button></div><div class="hub-end"><button class="hub-btn" id="hub-appt-export">Export .ics</button><button class="hub-btn danger" id="hub-appt-delete">Delete appointment</button></div><p class="hub-caption">Export adds a copy to a calendar of your choice. Later Hub edits and deletions do not update exported copies.</p>`);paintThumbs(d);action($('#hub-appt-open-contact',d),()=>c?showContact(c.id):null);action($('#hub-appt-open-vehicle',d),async()=>{d.close();$$('dialog.hub-dialog').forEach(x=>x.close());M.close();await Core.showVehicle?.(v.id);});action($('#hub-appt-edit',d),()=>{d.close();return editAppointment(id,{onSaved:onChanged});});$('#hub-appt-export',d).onclick=()=>download(new Blob([H.ics(a)],{type:'text/calendar;charset=utf-8'}),'LotKeys-appointment.ics');action($('#hub-appt-delete',d),async()=>{if(!confirm('Delete this Hub appointment? Calendar copies already exported are not deleted.'))return;await S.removeAppointment(id);d.close();await onChanged?.();});}
async function decorateInternal(id){await loadLocal();updateBadge();const p=panel();if(!p||p.dataset.conversationId!==id)return;const old=$('.hub-internal-tools',p);old?.remove();const tools=document.createElement('div');tools.className='hub-internal-tools';tools.innerHTML='<button class="hub-btn" data-internal="appointment">▦ Appointment</button><button class="hub-btn" data-internal="note">📝 Note</button><button class="hub-btn" data-internal="questions">❔ Questions</button><button class="hub-btn" data-internal="file">Photo / document</button>';$('.lkmsg-head',p)?.after(tools);$$('[data-internal]',tools).forEach(b=>action(b,async()=>{const c=await chooseContact(id);if(!c)return;if(b.dataset.internal==='appointment')return editAppointment(null,{contactId:c.id});if(b.dataset.internal==='note')return noteDialog(c.id);if(b.dataset.internal==='questions')return questionsDialog(c.id);return attachments(c.id);}));const share=$('#lkmsg-share',p);if(share)share.onclick=()=>{const d=modal('Add to this conversation',`<div class="hub-grid"><button class="hub-btn primary" id="hub-internal-share-original">Send a LotKeys attachment</button><button class="hub-btn" id="hub-internal-private">Save private customer content</button></div><p class="hub-caption">Private content is kept in your contact folder and is not sent to the other person.</p>`);action($('#hub-internal-share-original',d),()=>{d.close();M.share(id);});action($('#hub-internal-private',d),()=>{d.close();plusMenu('', '',id);});};}
